// Verificar plan (ADR-068) — lo PRIMERO después de leer la config, y el orden ES la decisión:
// verifica antes de que ninguna etapa gaste ni escriba nada.
//
// 🔴 Qué afirma, y por qué no se puede afirmar en ningún otro lado. La fachada DERIVA el pipeline
// de `instances.workflow_id`; nadie se lo pide (ADR-068). Entonces un plan que dice otra cosa
// significa que este workflow está apuntado a una instancia ajena, y **ese fallo no llega como
// error: llega como un documento bien formado**, con voces y referentes de verdad adentro — los de
// reels. Una corrida así termina en verde habiendo colectado del banco equivocado.
//
// Corta con el run YA ABIERTO a propósito: la fila queda, y el error handler global la marca
// `fallo` por `params.execution_id` (ADR-054).

const plan = $('Leer plan (fachada)').first().json || {};

if (plan.pipeline !== 'linkedin') {
  throw new Error(
    "run-plan devolvió pipeline='" + plan.pipeline + "' (esperaba 'linkedin'): esta corrida está " +
      'apuntada a una instancia que no es de LinkedIn. No se colectó ni se escribió nada.',
  );
}

const voces = Array.isArray(plan.voces) ? plan.voces : [];
const referentes = Array.isArray(plan.referentes) ? plan.referentes : [];

// 🔴 Lo que activa una voz en LinkedIn es que EXISTA SU PERFIL, jamás `voces.activo` (ADR-067).
// El plan de `ambito=motor` ya filtró por eso, así que `configurada` viene true en todas. Se
// vuelve a contar acá porque son dos cifras distintas en `ambito=completo`, y la diferencia entre
// ellas es lo único que delataría que este nodo está leyendo el plan equivocado.
const conPerfil = voces.filter(function (v) { return (v.fields || {}).configurada === true; });

const conteo = {
  pipeline: plan.pipeline,
  plan_version: plan.version,
  voces: voces.length,
  voces_con_perfil: conPerfil.length,
  referentes_activos: referentes.length,
};

// Con 0 voces no hay de quién escribir y con 0 referentes no hay de qué. La corrida SIGUE y
// entrega 0, que es la respuesta correcta y no un error — pero no puede ser muda: un run en verde
// sin piezas se lee como "el motor no encontró nada" cuando lo que pasa es que nadie lo configuró.
const avisos = [];
if (conPerfil.length === 0) avisos.push('0 voces con perfil: no hay de quién escribir (Fase 0.3 de plan-motor-linkedin)');
if (referentes.length === 0) avisos.push('0 referentes activos: el banco está vacío (Fase 0.5)');

console.log('[Verificar plan] ' + JSON.stringify(conteo) + (avisos.length ? ' · ' + avisos.join(' · ') : ''));
return [{ json: { conteo: conteo, avisos: avisos } }];

// Colectar (stub personal) — Fase 1.1 de plan-motor-linkedin. **ES UN STUB, y tiene que seguir
// siéndolo hasta la 1.4**, que lo reemplaza por la lectura real de las filas `fuente: archivo`
// del plan.
//
// Por qué existe un nodo de mentira: la cadena entera —tenant, FK, RLS, dedup, R-1, R-2,
// PostgREST— corre y se verifica ANTES de gastar un peso en Apify o en un LLM. Si la pieza aparece
// en el Feed, lo que falta es contenido, no cableado.
//
// 🔴 NO INVENTA LA FIRMA. Sale de `voces[].fields.firma`, que es la columna `not null` de la
// `020` §3 (R-2, ADR-055 §4). Una firma escrita acá sería la casa firmando con un texto que nadie
// aprobó, y encima haría pasar el validador de la etapa siguiente sin haber probado nada.

const plan = $('Leer plan (fachada)').first().json || {};
const voces = (Array.isArray(plan.voces) ? plan.voces : []).filter(function (v) {
  return (v.fields || {}).configurada === true;
});

// Sin voz configurada no hay pieza posible: la firma es obligatoria y no hay de dónde sacarla.
// Devuelve UN item igual, con `piezas: []`. Un code node que devuelve [] corta su rama entera, y
// acá eso todavía es seguro sólo porque el cierre del run cuelga de `Calidad` en la rama hermana.
if (voces.length === 0) {
  console.log('[Colectar] 0 voces con perfil: no hay de quién escribir. 0 piezas.');
  return [{ json: { piezas: [], stub: true, motivo: 'sin voces con perfil' } }];
}

const voz = voces[0];
const nombreVoz = (voz.fields || {}).nombre || voz.id;
const firma = (voz.fields || {}).firma;

// Dos piezas, y la segunda está rota A PROPÓSITO: es la única forma de que una corrida real pruebe
// que `Calidad` está CABLEADA y no solamente presente. Es la lección del setteo por WhatsApp y la
// del guard de ADR-029 — código correcto que nadie ejecuta protege exactamente cero. La rota viola
// R-1 (línea en blanco después de la primera línea del gancho, que es justo lo que esconde el post
// detrás del "ver más") y tiene que quedar afuera. Si alguna vez aparece en el Feed, el bug es de
// cableado y se ve a simple vista.
//
// El `external_id` es FIJO a propósito: `unique (instance_id, external_id)` +
// `resolution=ignore-duplicates` hacen que la segunda corrida no duplique nada. Correr esto dos
// veces es seguro y deja UNA fila.
const piezas = [
  {
    external_id: 'stub-personal-ok',
    carril: 'personal',
    fuente: 'archivo',
    titulo: 'Pieza de prueba del carril personal',
    texto: [
      'Esta pieza no la escribió un modelo.',
      'La emite el stub de la Fase 1.1 para probar el cableado.',
      'Si la estás viendo en el Feed, la cadena entera funciona.',
      '',
      'Lo que prueba: que el tenant viaja, que la FK resuelve, que RLS deja escribir, que el dedup ' +
        'no duplica y que el validador determinista dejó pasar lo que cumple R-1 y R-2.',
      '',
      'Lo que NO prueba: que la máquina escriba bien. Eso empieza cuando exista `generar`.',
      '',
      firma,
    ].join('\n'),
    voz_id: voz.id,
    firma: firma,
  },
  {
    external_id: 'stub-personal-r1',
    carril: 'personal',
    fuente: 'archivo',
    titulo: 'Pieza de prueba que TIENE que ser rechazada (R-1)',
    texto: ['Un gancho de una sola línea.', '', 'Y el resto del post acá abajo.', '', firma].join('\n'),
    voz_id: voz.id,
    firma: firma,
  },
];

if (voces.length > 1) {
  console.log('[Colectar] ' + voces.length + ' voces con perfil; el stub usa la primera (' + nombreVoz +
    '). Las demás entran con la 1.4.');
}
console.log('[Colectar] ' + piezas.length + ' piezas fijas (stub) para la voz ' + nombreVoz);
return [{ json: { piezas: piezas, stub: true, voz_id: voz.id } }];

// Calidad — el validador determinista de ADR-055 §4. Corre DESPUÉS del LLM y ANTES de que nada
// llegue a un humano. **Es código, no prompt**, y la diferencia no es de estilo: un prompt que pide
// "no pongas línea en blanco en el gancho" falla en silencio una de cada N veces y nadie se entera
// hasta que el post está publicado.
//
// Solo R-1 y R-2, que son las dos que se imponen a TODAS las voces. R-3 (espaciado) y R-4
// (separación mínima entre posts) son preferencia de la persona, viven como placeholder por voz y
// no se validan acá — R-4 ni siquiera es del post, es de la cola.
//
// 🔑 Las dos reglas se tratan distinto, y no es comodidad: lo decide quién es dueño del texto.
//   · R-1 → RECHAZO. El gancho es contenido. Código no puede inventar uno.
//   · R-2 → REPARACIÓN. La firma es texto de la CASA, guardado por voz (`020` §3). Ponerla no es
//     escribir. La única reparación que existe es agregarla al cierre cuando falta ENTERA: si
//     aparece en el medio del post se rechaza, porque agregarla la duplicaría y moverla ya es
//     reescribir.

const MIN_LINEAS_GANCHO = 2;
const MAX_LINEAS_GANCHO = 3;

// Colapsa todo espacio a uno solo y recorta. Es para COMPARAR la firma, no para guardarla: el LLM
// puede reflowear el salto de línea de adentro de la firma sin cambiar una palabra, y esa
// diferencia no es una violación de R-2.
function normalizar(s) {
  return String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
}

// El gancho es el PRIMER BLOQUE: todo lo que hay hasta la primera línea en blanco. Por definición
// no tiene línea en blanco adentro — lo que R-1 mide es cuántas líneas quedaron de ese lado. Un
// `\n\n` después de la línea 1 deja un gancho de 1 y esconde el post detrás del "ver más".
//
// ⚠️ Límite conocido y deliberado: cuenta SALTOS DE LÍNEA, no líneas visuales. Una línea larga que
// envuelve en el teléfono se cuenta como una sola. No hay forma de saber el ancho del viewport
// desde un code node, y la regla de la entrevista habla de `\n\n`, que sí se puede medir.
function lineasDelGancho(texto) {
  const limpio = String(texto == null ? '' : texto).replace(/\r\n/g, '\n');
  const bloque = limpio.split(/\n[ \t]*\n/)[0] || '';
  return bloque
    .split('\n')
    .map(function (l) { return l.trim(); })
    .filter(function (l) { return l !== ''; });
}

function evaluar(pieza) {
  const texto = String(pieza.texto == null ? '' : pieza.texto).replace(/\r\n/g, '\n').replace(/\s+$/, '');
  const firma = String(pieza.firma == null ? '' : pieza.firma);

  if (normalizar(texto) === '') return { estado: 'rechazada', motivo: 'sin_texto' };

  // Una voz sin firma no es un problema del post: es config faltante, y es estructural. La `020`
  // §3 declara `firma not null`, así que esto sólo puede pasar con un plan de `ambito=completo`
  // (donde las voces sin perfil viajan con los campos en null). Se rechaza, no se inventa nada.
  if (normalizar(firma) === '') return { estado: 'rechazada', motivo: 'voz_sin_firma (R-2)' };

  const gancho = lineasDelGancho(texto);
  if (gancho.length < MIN_LINEAS_GANCHO || gancho.length > MAX_LINEAS_GANCHO) {
    return {
      estado: 'rechazada',
      motivo: 'gancho_de_' + gancho.length + '_lineas (R-1: entre ' + MIN_LINEAS_GANCHO + ' y ' + MAX_LINEAS_GANCHO + ')',
    };
  }

  const nt = normalizar(texto);
  const nf = normalizar(firma);
  if (nt.slice(-nf.length) === nf) return { estado: 'ok', texto: texto };
  if (nt.indexOf(nf) !== -1) return { estado: 'rechazada', motivo: 'firma_fuera_del_cierre (R-2)' };
  return { estado: 'reparada', motivo: 'firma_agregada (R-2)', texto: texto + '\n\n' + firma.trim() };
}

const entrada = $input.first().json || {};
const piezas = Array.isArray(entrada.piezas) ? entrada.piezas : [];

const aprobadas = [];
const rechazos = [];
let reparadas = 0;

piezas.forEach(function (p) {
  const v = evaluar(p);
  if (v.estado === 'rechazada') {
    rechazos.push({ external_id: p.external_id || null, motivo: v.motivo });
    return;
  }
  if (v.estado === 'reparada') reparadas++;
  aprobadas.push(Object.assign({}, p, { texto: v.texto, calidad: v.estado }));
});

const calidad = {
  evaluadas: piezas.length,
  aprobadas: aprobadas.length,
  reparadas: reparadas,
  rechazadas: rechazos.length,
  rechazos: rechazos,
};

// 🔴 Un rechazo de calidad NO va a `app.descartes_linkedin`, y no es un olvido: esa tabla es para
// los near-miss del GATE (ADR-036), o sea piezas que un humano podría querer auditar como falso
// negativo. Un post malformado no es un falso negativo, es una falla de generación — y su sumidero
// es `runs.metricas`, que es donde se ve si el LLM empezó a romper R-1 sistemáticamente.
rechazos.forEach(function (r) { console.log('[Calidad] ✗ ' + r.external_id + ': ' + r.motivo); });
console.log('[Calidad] ' + JSON.stringify(calidad));
return [{ json: { piezas: aprobadas, calidad: calidad } }];

// Preparar candidatos — filas planas para PostgREST contra `app.candidatos_linkedin`. Es la
// mitad de escritura de ADR-035: *n8n lee su config por la fachada, escribe sus resultados por
// PostgREST*.

const entrada = $input.first().json || {};
const piezas = Array.isArray(entrada.piezas) ? entrada.piezas : [];
const instanceId = $('Config').first().json.instance_id;

const filas = piezas.map(function (p) {
  return {
    // De quién es esta fila. `instance_id` es `not null` y SIN default en la `020` §4 a
    // propósito: un insert que se olvide del tenant falla en el primer intento en vez de
    // atribuirle datos a la instancia equivocada. Sale del payload del webhook (ADR-048).
    instance_id: instanceId,
    // Lo que dedupea, y va SCOPEADO por instancia. El unique global fue el peor hallazgo del
    // diagnóstico multi-tenant: le vacía el supply a la segunda empresa sin un solo error.
    external_id: p.external_id,
    carril: p.carril,
    fuente: p.fuente,
    titulo: p.titulo,
    texto: p.texto,
    idioma: p.idioma || null,
    url: p.url || null,
    autor: p.autor || null,
    imagen_url: p.imagen_url || null,
    referente_id: p.referente_id || null,
    proyecto_id: p.proyecto_id || null,
    voz_id: p.voz_id || null,
    estado: 'nuevo',
  };
});

console.log('[Entrega] ' + filas.length + ' candidatos a app.candidatos_linkedin');

// Sin filas no hay POST: devolver [] corta ESTA rama, que es lo correcto — no hay nada que
// escribir y un POST con `[]` sería un request al pedo contra un nodo fail-closed.
// 🔴 Ese corte es seguro por UNA razón y sólo una: el cierre del run cuelga de `Calidad` en la
// rama hermana, no de acá. Si alguien vuelve a poner `Resumen del run` en serie detrás del POST,
// toda corrida sin piezas —hoy, con 0 voces, TODAS— deja el run `en_curso` hasta el barrido de la
// corrida siguiente.
return filas.length ? [{ json: { filas: filas } }] : [];

// Resumen del run — el embudo de la corrida a `runs.metricas`. `Cerrar run` persiste
// `$json.metricas` tal cual.
//
// 🔑 Cuelga de `Calidad` en una rama HERMANA de la entrega, no detrás de ella, y esa es la
// decisión que hace que el run cierre SIEMPRE: `Preparar candidatos` devuelve [] cuando no hay
// nada que escribir, y un [] corta su rama entera. Con el cierre ahí atrás, toda corrida sin
// piezas —hoy, con 0 voces, todas— dejaría la fila `en_curso` hasta el barrido siguiente.
// La rama de entrega corre PRIMERO porque su destino tiene Y menor (320 < 480): en n8n v1 el orden
// de las hermanas lo decide la posición en el canvas, no el array de `connections`.
//
// ⚠️ La contracara, y hay que saberla: desde acá NO se ve si el POST entró. No se puede
// referenciar un nodo de la rama hermana —no es ancestro, y `auditar-workflows.mjs` lo caza—. Y
// no hace falta: `POST Candidatos` es fail-closed, así que si falla la ejecución aborta y el
// error handler global marca el run `fallo` por `params.execution_id` (ADR-054).

const verificado = $('Verificar plan (ADR-068)').first().json || {};
const conteo = verificado.conteo || {};
const colecta = $('Colectar (stub personal)').first().json || {};
const calidad = ($input.first().json || {}).calidad || {};

const avisos = (verificado.avisos || []).slice();

// El stub emite 2 piezas y una está rota a propósito (R-1). Mientras siga siendo el stub, ese
// reparto ES la prueba de que `Calidad` está cableada: si entraran las dos, el validador no está
// corriendo. Aviso y no throw — qué hacer con una corrida de prueba lo decide quien la mira.
if (colecta.stub === true && (calidad.evaluadas || 0) > 0 && (calidad.rechazadas || 0) === 0) {
  avisos.push('el stub emite una pieza que viola R-1 y NINGUNA fue rechazada: revisá que Calidad esté cableada');
}

const metricas = {
  etapa: colecta.stub === true ? 'stub (Fase 1.1: colectar de mentira)' : 'motor',
  pipeline: conteo.pipeline,
  voces_con_perfil: conteo.voces_con_perfil,
  referentes_activos: conteo.referentes_activos,
  colectadas: calidad.evaluadas || 0,
  aprobadas: calidad.aprobadas || 0,
  reparadas: calidad.reparadas || 0,
  rechazadas: calidad.rechazadas || 0,
  rechazos: calidad.rechazos || [],
  entregadas: calidad.aprobadas || 0,
  avisos: avisos,
};

console.log('[Resumen] ' + JSON.stringify(metricas));
return [{ json: { metricas: metricas } }];
